import { GetGlobalPostageBatchResponse, GetGlobalPostageBatchesResponse } from "../types/schema/stamps.js";
import { http } from "../utils/http.js";
const batchesEndpoint = 'batches';
/**
 * Raw HTTP calls for the `/batches` endpoint.
 */
export async function getGlobalPostageBatch(requestOptions, id) {
  const response = await http(requestOptions, {
    method: 'get',
    url: `${batchesEndpoint}/${id}`,
    responseType: 'json'
  });
  return GetGlobalPostageBatchResponse.parse(response.data);
}
export async function getAllGlobalPostageBatches(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    url: batchesEndpoint,
    responseType: 'json'
  });
  return GetGlobalPostageBatchesResponse.parse(response.data).batches;
}